preConditionHook:
// TARGET A FRACTION OF THE MARKET'S OWN LAST PULLBACK. Brooks: if the last
// pullback ran about fifteen ticks, look to exit ten to fifteen ticks up from
// the low. The distance measure is the market's own most recent swing-high to
// swing-low span, and the target is that span times profitFraction measured up
// from the swing low the trade came off.
//
// FROZEN AT ENTRY. The span and the level are captured once, on the fill bar
// (BarsSinceEntry() == 0, VERIFIED as 0 on the fill bar, 0 while flat and
// restarting through a reversal), which holds the target still while the
// position is open; a level recomputed from the rolling pivots would walk away
// from the trade as new pivots confirm. Both scans run UNCONDITIONALLY on every
// bar -- only the freeze is conditional -- so Max Bars Back must cover the scan
// regardless, matching the twin's unconditional series calls.
//
// THE -1 SENTINEL is the hazard, as in SwingPivotTarget: a window with no pivot
// leaves the level at -1, which as a price sits below every real price, so an
// unguarded long target would be reached on the entry bar. havePb is that guard,
// and it also requires the swing high to sit above the swing low.
//
// PIVOT SCAN inlined rather than referencing SwingHigh.json -- rules here never
// reference each other. MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt,
// @ES 60 min): the pivot bar is AT OR ABOVE the swingStrength older bars and
// STRICTLY ABOVE the swingStrength newer bars -- bars-ago indexing, so the newer
// bars are the smaller k and take el_gt / el_lt, the older el_ge / el_le. The
// confirmation lag is exactly swingStrength bars, candidate offsets are
// swingStrength..lookbackBars-1, and the neighbourhood reaches swingStrength
// bars past the window, so the deepest bar touched is
// lookbackBars - 1 + swingStrength. Scanning newest-first with a break
// reproduces "occurrence 1 is the most recent confirmed pivot". The comparisons
// carry the 2.22e-12 relational tolerance. The low side's tie sense is the
// mirror of the measured high-side rule. No WFSafe_SwingHigh exists, so plain EL
// governs.
//
// Not SwingPivotTarget, which exits AT the pivot and re-reads it every bar; not
// PatternHeightMeasuredMoveTarget, which spans a fixed refBars window where this
// spans two confirmed pivots. At profitFraction = 1 the level coincides with
// SwingPivotTarget's pivotIndex 1 on trades entered before a new pivot confirms,
// which is why the default is 0.8.
pivS = (int)swingStrength;
pivW = (int)lookbackBars;
pbHiBar = -1.0;
pbHiPx = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) { pbHiBar = (double)j; pbHiPx = high[j]; break; }
}
pbLoBar = -1.0;
pbLoPx = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) { pbLoBar = (double)j; pbLoPx = low[j]; break; }
}
if (ctx.BarsSinceEntry() == 0) {
    havePb = (pbHiBar != -1.0) && (pbLoBar != -1.0) && el_gt(pbHiPx, pbLoPx);
    pbTgtUp = pbLoPx + profitFraction * (pbHiPx - pbLoPx);
    pbTgtDn = pbHiPx - profitFraction * (pbHiPx - pbLoPx);
}
